#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    if (n < 3) { printf("%lld\n", *max_element(a.begin(), a.end())); return 0; }
    // dp: value left at the front -> least cost paid so far.
    map<long long, long long> dp;
    auto relax = [](map<long long, long long> &m, long long keep, long long cost) {
        auto it = m.find(keep);
        if (it == m.end() || cost < it->second) m[keep] = cost;
    };
    long long x = a[0], y = a[1], z = a[2];
    relax(dp, x, max(y, z));
    relax(dp, y, max(x, z));
    relax(dp, z, max(x, y));
    int i = 3;
    while (i + 1 < n) {
        long long p = a[i], q = a[i + 1];
        map<long long, long long> nxt;
        // Of the carried value and the next two, keep one and pay for the other two.
        for (auto [carry, cost] : dp) {
            relax(nxt, carry, cost + max(p, q));
            relax(nxt, p, cost + max(carry, q));
            relax(nxt, q, cost + max(carry, p));
        }
        dp.swap(nxt);
        i += 2;
    }
    long long best = LLONG_MAX;
    for (auto [carry, cost] : dp) best = min(best, cost + (i < n ? max(carry, a[i]) : carry));
    printf("%lld\n", best);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static void relax(HashMap<Long, Long> m, long keep, long cost) { m.merge(keep, cost, Math::min); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (n < 3) { System.out.println(Arrays.stream(a).max().getAsLong()); return; }
        // dp: value left at the front -> least cost paid so far.
        HashMap<Long, Long> dp = new HashMap<>();
        long x = a[0], y = a[1], z = a[2];
        relax(dp, x, Math.max(y, z));
        relax(dp, y, Math.max(x, z));
        relax(dp, z, Math.max(x, y));
        int i = 3;
        while (i + 1 < n) {
            long p = a[i], q = a[i + 1];
            HashMap<Long, Long> nxt = new HashMap<>();
            // Of the carried value and the next two, keep one and pay for the other two.
            for (Map.Entry<Long, Long> e : dp.entrySet()) {
                long carry = e.getKey(), cost = e.getValue();
                relax(nxt, carry, cost + Math.max(p, q));
                relax(nxt, p, cost + Math.max(carry, q));
                relax(nxt, q, cost + Math.max(carry, p));
            }
            dp = nxt;
            i += 2;
        }
        long best = Long.MAX_VALUE;
        for (Map.Entry<Long, Long> e : dp.entrySet()) {
            long carry = e.getKey(), cost = e.getValue();
            best = Math.min(best, cost + (i < n ? Math.max(carry, a[i]) : carry));
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func relax(m map[int]int, keep, cost int) {
	if old, ok := m[keep]; !ok || cost < old {
		m[keep] = cost
	}
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	if n < 3 {
		fmt.Println(max(a[0], a[n-1]))
		return
	}
	// dp: value left at the front -> least cost paid so far.
	dp := map[int]int{}
	x, y, z := a[0], a[1], a[2]
	relax(dp, x, max(y, z))
	relax(dp, y, max(x, z))
	relax(dp, z, max(x, y))
	i := 3
	for i+1 < n {
		p, q := a[i], a[i+1]
		nxt := map[int]int{}
		// Of the carried value and the next two, keep one and pay for the other two.
		for carry, cost := range dp {
			relax(nxt, carry, cost+max(p, q))
			relax(nxt, p, cost+max(carry, q))
			relax(nxt, q, cost+max(carry, p))
		}
		dp = nxt
		i += 2
	}
	best := math.MaxInt64
	for carry, cost := range dp {
		if i < n {
			best = min(best, cost+max(carry, a[i]))
		} else {
			best = min(best, cost+carry)
		}
	}
	fmt.Println(best)
}
